import struct,zlib,json,glob
from datetime import datetime,timezone
from zoneinfo import ZoneInfo
shards=[]
for sid,fn in enumerate(sorted(glob.glob('/app/data/journals/shard-*.jnl'))):
 b=open(fn,'rb').read(); pos=0; ev=[]
 while True:
